INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"821cc8c8-8c80-5ce6-a03a-0b799593a70d","title":"Life Orientation · Grade 11 · Term 2: Power relations and environmental responsibility","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"Which action helps challenge unequal power in a school group?","options":["Let one member silence everyone","Treat intimidation as leadership","Give members safe ways to speak and respond fairly to concerns","Dismiss every complaint automatically"],"correct_index":2,"explanation":"Fair participation and accountability can reduce harmful power imbalances. Address intimidation through appropriate school support processes."},{"question":"A learner hears a disclosure of gender-based violence. What is a supportive response?","options":["Blame the person harmed","Share the story publicly without consent","Promise to investigate alone through confrontation","Listen without blame and help access trusted, appropriate support"],"correct_index":3,"explanation":"Support begins with listening, safety and appropriate help. Avoid blame, gossip or actions that may increase risk."},{"question":"Why can environmental pollution become a public-health issue?","options":["People can be exposed through air, water or food","Pollution never reaches people","Only appearance matters","Every pollutant has identical effects"],"correct_index":0,"explanation":"Exposure pathways and pollutant types influence risk. Investigate evidence and use appropriate authorities rather than making unsupported health claims."},{"question":"Which community action supports responsible citizenship?","options":["Dump waste elsewhere at night","Report illegal dumping through suitable channels and help plan safe prevention","Ignore vulnerable residents","Post private accusations without evidence"],"correct_index":1,"explanation":"Responsible action uses safe, lawful channels and cooperation. Prevention should address causes and include affected people."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Power relations and environmental responsibility. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Power relations and environmental responsibility","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"fb492f1d-cd0f-57e5-a2ff-fc51a02e7441","title":"Life Orientation · Grade 11 · Term 3: Lifestyle choices and career competence","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"A learner is sleeping too little to keep studying longer. What is the most constructive response?","options":["Assume less sleep always improves memory","Use unverified substances to stay awake","Abandon all schoolwork permanently","Adjust the plan to include rest and seek support with workload"],"correct_index":3,"explanation":"Rest supports attention and learning. A realistic schedule and timely support are more sustainable than repeated exhaustion."},{"question":"Which is a transferable work skill?","options":["Communicating clearly and collaborating on tasks","Memorising one person's phone number only","Refusing all feedback","Avoiding every new problem"],"correct_index":0,"explanation":"Transferable skills can be used across roles and settings. Learners can develop them through projects, responsibilities and reflection."},{"question":"A job advertisement requires a skill the learner has not yet developed. What is a useful next step?","options":["Invent experience on the CV","Identify credible training and practise the skill while checking other requirements","Assume every training advert is legitimate","Pay anyone promising a guaranteed job"],"correct_index":1,"explanation":"Compare the gap with reliable training options and develop evidence of competence. Honest applications protect credibility."},{"question":"What does work ethics include?","options":["Concealing mistakes from everyone","Using others' work without credit","Reliability, honesty and respect for responsibilities","Ignoring agreed safety procedures"],"correct_index":2,"explanation":"Ethical conduct involves accountability and consideration of others. Ask for help and correct errors rather than hiding them."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Lifestyle choices and career competence. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Lifestyle choices and career competence","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"81011bca-8754-531c-87eb-3ad3c0a0ef6f","title":"Life Orientation · Grade 11 · Term 4: Human rights, moral reasoning and exam planning","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"How can a class discuss a moral disagreement constructively?","options":["Clarify values, consider evidence and respect people while evaluating ideas","Attack people instead of arguments","Ban every question","Assume one slogan resolves all dilemmas"],"correct_index":0,"explanation":"Reasoned discussion distinguishes claims, values and consequences. Respect does not prevent careful criticism of an argument."},{"question":"A learner rereads notes but struggles in tests. What is a useful change?","options":["Only buy more highlighters","Practise retrieval and timed questions, then review errors","Stop checking answers","Avoid difficult topics entirely"],"correct_index":1,"explanation":"Practice reveals what can be recalled and applied under test conditions. Feedback helps target the next study session."},{"question":"Why should a study plan be revised after a practice test?","options":["One score determines lifelong ability","The original plan must never change","Errors provide evidence about what needs more attention","Only correct answers deserve review"],"correct_index":2,"explanation":"Use mistakes diagnostically: identify the concept, practise it and check again. A score is information about that attempt, not a fixed label."},{"question":"What supports a harmonious multi-religious school community?","options":["Compulsory agreement on every belief","Excluding minority views from all activities","Stereotyping every member of a religion","Equal dignity, respectful dialogue and fair participation"],"correct_index":3,"explanation":"Respect for rights supports coexistence amid differences. Policies should protect participation and avoid discrimination."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Human rights, moral reasoning and exam planning. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Human rights, moral reasoning and exam planning","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"b8584c78-03cc-593d-83ab-2a6c3cf04960","title":"English HL · Grade 11 · Term 2: Argument, inference and summary","subject":"English HL","grade":"Grade 11","questions":[{"question":"What contrast is introduced by yet?","options":["The library had no books","The survey happened before the school existed","Every learner stopped travelling","Longer opening hours did not lead to much higher attendance"],"correct_index":3,"explanation":"Yet signals an unexpected outcome compared with the likely expectation that more hours would increase use.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door."},{"question":"Which factor limits access according to the survey?","options":["Transport timing","The colour of the shelves","The price of every textbook","A ban on reading"],"correct_index":0,"explanation":"Learners identify the last taxi's departure as a constraint. Attribute the claim to the survey rather than inventing unrelated causes.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door."},{"question":"Which summary preserves the main point most accurately?","options":["The librarian cancelled all taxis.","Longer library hours alone did not solve access because transport remained a barrier.","Nobody wanted to read anything.","The library became permanently inaccessible."],"correct_index":1,"explanation":"A sound summary selects the central relationship without adding unsupported certainty or detail.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door."},{"question":"What does an unlocked door represent in the final sentence?","options":["Proof that all learners can attend","An instruction to remove the door","A narrow idea of access based only on physical opening","A literal taxi timetable"],"correct_index":2,"explanation":"The image highlights the difference between formal availability and practical access. Transport makes the distinction meaningful.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Argument, inference and summary. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Argument, inference and summary","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"1f71af16-2313-57f7-a9ab-77e43334b2d1","title":"English HL · Grade 11 · Term 3: Advertising claims and critical literacy","subject":"English HL","grade":"Grade 11","questions":[{"question":"Which word creates an unjustifiably exclusive claim?","options":["Only","Poster","Three","Beneath"],"correct_index":0,"explanation":"Only excludes all other routes to success. The passage provides no evidence for such a broad claim.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided."},{"question":"What persuasive function do the smiling learners mainly serve?","options":["They establish a controlled comparison","They associate the app with positive outcomes and satisfaction","They prove every user succeeds","They provide the missing results dataset"],"correct_index":1,"explanation":"Visual endorsement can create positive associations. It does not by itself establish effectiveness or causation.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided."},{"question":"What evidence would best help evaluate the claim?","options":["More smiling photographs alone","A larger slogan","Reliable results with clear methods and an appropriate comparison","An unrelated celebrity's favourite colour"],"correct_index":2,"explanation":"Evidence needs to address the claim, including how outcomes were measured and compared. Design and context matter.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided."},{"question":"Which revision makes the slogan more defensible?","options":["Guaranteed success for every learner","No effort needed for top marks","All other learning is useless","A study tool designed to support your preparation"],"correct_index":3,"explanation":"The revised wording describes intended support without unsupported guarantees or dismissing other learning routes.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Advertising claims and critical literacy. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Advertising claims and critical literacy","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"83702d37-1150-5cdc-bad4-e35b9639c3cf","title":"English HL · Grade 11 · Term 4: Narrative perspective and imagery","subject":"English HL","grade":"Grade 11","questions":[{"question":"Who narrates the passage?","options":["An all-knowing third-person narrator","A first-person narrator","A second-person narrator throughout","A named newspaper editor"],"correct_index":1,"explanation":"I and my indicate first-person narration. The passage does not give direct access to every character's thoughts.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."},{"question":"What does its silence seemed louder suggest?","options":["The watch is literally ringing louder","The narrator has measured sound levels","The watch's emotional significance is strongly felt despite its silence","The drawer contains a loudspeaker"],"correct_index":2,"explanation":"The apparent contradiction conveys emotional intensity. Explain the contextual effect rather than insisting on a literal sound.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."},{"question":"Why should the narrator's motive for closing the drawer remain qualified?","options":["The text states every thought explicitly","A first-person narrator can never be interpreted","The sister has already explained it","The action suggests attachment but does not state the full motive"],"correct_index":3,"explanation":"Inference can identify possibilities supported by details while recognising that the narrator leaves some meaning unstated.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."},{"question":"Which response gives the strongest textual support for attachment?","options":["Keeping the old watch and reacting to its silence suggest lasting emotional value.","The narrator must be a watchmaker.","The sister definitely plans to sell it.","All old objects are expensive."],"correct_index":0,"explanation":"The response links a claim to two details and avoids unsupported assumptions about occupation or intentions.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Narrative perspective and imagery. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Narrative perspective and imagery","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"10a9aee8-8da1-5ba9-bc87-437b2dcda684","title":"Afrikaans HL · Grade 11 · Term 2: Argument en samevatting","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter teenstelling dui maar aan?","options":["Langer ure lei nie tot veel beter bywoning nie","Die biblioteek het geen boeke nie","Die opname is eeue oud","Geen leerder reis ooit nie"],"correct_index":0,"explanation":"Maar wys dat die uitkoms verskil van wat 'n mens waarskynlik sou verwag.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur."},{"question":"Watter hindernis noem die leerders?","options":["Die kleur van die rakke","Die taxi se vertrektyd","Die titel van elke boek","Die gebrek aan vensters"],"correct_index":1,"explanation":"Die teks noem vervoer as 'n praktiese beperking. Gebruik die opname se inhoud as bewys.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur."},{"question":"Watter samevatting behou die kernbetekenis?","options":["Die skool kanselleer alle taxi's.","Geen leerder wil lees nie.","Langer ure alleen verbeter nie toegang as vervoer 'n hindernis bly nie.","Die biblioteek bly permanent gesluit."],"correct_index":2,"explanation":"'n Samevatting selekteer die hoofverband sonder om ongegronde besonderhede by te voeg.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur."},{"question":"Wat verteenwoordig 'n oop deur in die slotsin?","options":["Gewaarborgde toegang vir elke leerder","Die prys van vervoer","Die uitslag van 'n toets","Slegs die fisiese beskikbaarheid van die ruimte"],"correct_index":3,"explanation":"Die beeld kontrasteer formele beskikbaarheid met praktiese toegang. Die vervoerprobleem verduidelik die verskil.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Argument en samevatting. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Argument en samevatting","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"13c796ec-485d-5f43-baf9-9064951094ff","title":"Afrikaans HL · Grade 11 · Term 3: Advertensies en kritiese geletterdheid","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter woord maak die aanspraak uitsluitend?","options":["Drie","Enigste","Plakkaat","Sertifikate"],"correct_index":1,"explanation":"Enigste sluit ander moontlike paaie uit. Die teks bied nie bewyse vir so 'n wye aanspraak nie.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie."},{"question":"Wat is die oorredende funksie van die glimlaggende leerders?","options":["Hulle bewys alle gebruikers slaag","Hulle vorm 'n volledige ondersoek","Hulle verbind die produk met positiewe uitkomste","Hulle vervang alle uitslagdata"],"correct_index":2,"explanation":"Die beeld skep 'n positiewe assosiasie, maar bewys nie die produk se effektiwiteit nie.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie."},{"question":"Watter bykomende inligting sal die aanspraak die beste help toets?","options":["Net nog glimlaggende foto's","'n Groter slagspreuk","'n Ander agtergrondkleur","Betroubare uitslae met duidelike metodes en 'n gepaste vergelyking"],"correct_index":3,"explanation":"Bewyse moet by die aanspraak pas. Metodes en vergelykbaarheid bepaal hoe sterk die gevolgtrekking kan wees.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie."},{"question":"Watter herskrywing is meer verantwoordbaar?","options":["'n Hulpmiddel wat jou studievoorbereiding ondersteun","Sukses word vir almal gewaarborg","Geen werk is nodig nie","Alle ander leer is nutteloos"],"correct_index":0,"explanation":"Die herskrywing beskryf ondersteuning sonder 'n ongegronde waarborg of uitsluiting van ander leerwyses.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Advertensies en kritiese geletterdheid. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Advertensies en kritiese geletterdheid","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"f15a0b0b-00a9-5600-9375-dd13b4ea9d3b","title":"Afrikaans HL · Grade 11 · Term 4: Verteller en emosionele betekenis","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter vertelperspektief word gebruik?","options":["Alwetende derdepersoonsverteller","Tweedepersoonsverteller deurgaans","Eerstepersoonsverteller","Onpersoonlike nuusberig"],"correct_index":2,"explanation":"Ek en my wys dat die verhaal deur 'n deelnemende eerstepersoonsverteller vertel word.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."},{"question":"Wat suggereer sy stilte harder?","options":["Die horlosie lui letterlik harder","Daar is 'n luidspreker in die laai","Die verteller meet klankvlakke","Die horlosie se emosionele betekenis bly sterk"],"correct_index":3,"explanation":"Die skynbare teenstrydigheid beklemtoon gevoel eerder as 'n letterlike geluid.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."},{"question":"Waarom moet die verteller se motief versigtig geïnterpreteer word?","options":["Die handeling suggereer gehegtheid, maar die volle motief word nie uitgespel nie","Elke gedagte word volledig verduidelik","Die suster vertel die hele verhaal","'n Eerstepersoonsverhaal kan nie ontleed word nie"],"correct_index":0,"explanation":"Afleidings moet op besonderhede steun en erken waar die teks inligting ooplaat.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."},{"question":"Watter antwoord ondersteun gehegtheid die beste?","options":["Die verteller is beslis 'n horlosiemaker.","Die bewaring van die horlosie en die reaksie op sy stilte dui op emosionele waarde.","Die suster wil dit beslis verkoop.","Alle ou voorwerpe is duur."],"correct_index":1,"explanation":"Die antwoord verbind 'n interpretasie met twee teksbesonderhede sonder om 'n beroep of plan uit te dink.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Verteller en emosionele betekenis. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Verteller en emosionele betekenis","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"b659b6c2-d6d8-51ac-9cbb-908537fab05b","title":"isiXhosa HL · Grade 11 · Term 2: Isishwankathelo nengxoxo exhaswayo","subject":"isiXhosa HL","grade":"Grade 11","questions":[{"question":"Sesiphi isishwankathelo esichanekileyo?","options":["Bonke abafundi bayasichasa isindululo.","Indawo yokufunda iyaxhaswa, kodwa ukuthutha kusafuna ukusonjululwa.","Iiteksi ziza kubakho ubusuku bonke.","Ikomiti sele yakha isakhiwo esitsha."],"correct_index":1,"explanation":"Isishwankathelo sigcina ingcamango ephambili kunye nomqobo obalulekileyo ngaphandle kokongeza izigqibo ezinganikiweyo.","stimulus":"IKomiti yesikolo icebisa indawo yokufunda emva kwemini. Abafundi abaninzi bayasixhasa isindululo, kodwa abanye bathi iteksi yabo yokugqibela ihamba kwangoko. Ikomiti iza kubuza nangendlela yokuthutha."},{"question":"Yintoni umsebenzi wegama kodwa?","options":["Kukubonisa ukuba wonke umntu uyavuma.","Kukubala abafundi.","Kukwazisa inkcaso okanye umda kwingcamango engaphambili.","Kukwazisa igama lomntu."],"correct_index":2,"explanation":"Kodwa lidibanisa inkxaso yesindululo kunye nengxaki yokufikelela. Lunceda ukufunda uluvo olunamacala ahlukeneyo.","stimulus":"IKomiti yesikolo icebisa indawo yokufunda emva kwemini. Abafundi abaninzi bayasixhasa isindululo, kodwa abanye bathi iteksi yabo yokugqibela ihamba kwangoko. Ikomiti iza kubuza nangendlela yokuthutha."},{"question":"Luluphi uphando oluya kunceda isigqibo?","options":["Buza kuphela umbala abazithandayo.","Ungabandakanyi abafundi abakhwela iiteksi.","Bala iifestile zethala kuphela.","Buza abafundi ngamaxesha okuthutha nokufumaneka kwabo."],"correct_index":3,"explanation":"Idatha yokuthutha ihambelana ngqo nengxaki ekhankanyiweyo. Ukushiya iqela elichaphazelekayo ngaphandle kungalugqwetha uphando.","stimulus":"IKomiti yesikolo icebisa indawo yokufunda emva kwemini. Abafundi abaninzi bayasixhasa isindululo, kodwa abanye bathi iteksi yabo yokugqibela ihamba kwangoko. Ikomiti iza kubuza nangendlela yokuthutha."},{"question":"Leliphi igama eligcina umahluko obalulekileyo kwisishwankathelo?","options":["Abaninzi","Bonke","Akukho namnye","Ngokuqinisekileyo wonke umntu"],"correct_index":0,"explanation":"Abaninzi alithethi bonke. Ukugcina eli gama kuthintela ukwandisa ibango ngaphezu kobungqina.","stimulus":"IKomiti yesikolo icebisa indawo yokufunda emva kwemini. Abafundi abaninzi bayasixhasa isindululo, kodwa abanye bathi iteksi yabo yokugqibela ihamba kwangoko. Ikomiti iza kubuza nangendlela yokuthutha."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Isishwankathelo nengxoxo exhaswayo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Isishwankathelo nengxoxo exhaswayo","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=hEkvWcfU0LI%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"54b5dd62-e551-5dd5-896e-a82bbf7f182a","title":"isiXhosa HL · Grade 11 · Term 3: Ukufunda ngeliso elibukhali nokuvavanya ibango","subject":"isiXhosa HL","grade":"Grade 11","questions":[{"question":"Yeyiphi eyona ngxaki kubungqina?","options":["Akukho mntu unokufunda kwinkqubo.","Amanqaku awanakuze alinganiswe.","Amava omfundi omnye awanele ukungqina ifuthe kubo bonke.","Zonke iintengiso zibubuxoki."],"correct_index":2,"explanation":"Ubungqina bunomda kuba isampuli incinci kwaye akukho thelekiso lunikiweyo. Oku akuthethi ukuba inkqubo ayinakunceda mntu.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa."},{"question":"Leliphi ibango elilungelelanisiweyo?","options":["Inkqubo iqinisekisa impumelelo kubo bonke.","Akukho mfundi unokuxhamla.","Isibhengezo sele singqine unobangela.","Omnye umfundi uxela inzuzo; kufuneka uphando olubanzi."],"correct_index":3,"explanation":"Isivakalisi sigcina ubungqina obukhoyo size sicacise umda waso. Musa ukuthembisa okungalinganiswanga.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa."},{"question":"Yeyiphi idatha enokwenza uvavanyo lube ngcono?","options":["Amanqaku angaphambi nasemva kunye neqela elithelekisekayo.","Inani lemibala kwisibhengezo kuphela.","Igama lomshicileli kuphela.","Ubungakanani belogo kuphela."],"correct_index":0,"explanation":"Uthelekiso olucwangciswe kakuhle lunceda ukuvavanya utshintsho kunye nezinye izinto ezinokuluchaza.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa."},{"question":"Kutheni kufuneka kuqwalaselwe injongo yombhali?","options":["Injongo ithetha ukuba onke amabango ayinyaniso.","Usenokuba ufuna ukuthengisa inkqubo nokugxininisa izibonelelo.","Injongo yombhali isusa imfuneko yobungqina.","Umbhali akanakukhetha ulwazi."],"correct_index":1,"explanation":"Ukuqonda injongo yokuthengisa kunceda ukubuza ukuba loluphi ulwazi olukhethiweyo okanye olushiyiweyo.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukufunda ngeliso elibukhali nokuvavanya ibango. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","xhhl"],"metadata":{"term":3,"focus":"Ukufunda ngeliso elibukhali nokuvavanya ibango","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=hEkvWcfU0LI%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"3832adac-d345-55cc-990c-5be5f9d15113","title":"isiXhosa HL · Grade 11 · Term 4: Ilizwi lombalisi nentsingiselo efihlakeleyo","subject":"isiXhosa HL","grade":"Grade 11","questions":[{"question":"Ngubani obalisa esi sicatshulwa?","options":["Ngumbalisi ongazange abe yinxalenye yesiganeko.","Ngabantu abaninzi abathetha ngaxeshanye.","Sisibhengezo sevenkile.","Ngumlinganiswa obalisa ngamava akhe."],"correct_index":3,"explanation":"Izenzi ezithi Ndabeka, ndiza kunye ndalinda zibonisa umntu wokuqala. Simamela amava akhe ngendlela awabalisayo.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki."},{"question":"Yintoni umahluko obalulekileyo?","options":["Umbalisi uthi uza kuhamba kodwa uyema alinde.","Isitshixo sitshintsha sibe yileta.","Amanyathelo afika kwangoko.","Umnyango uyathetha."],"correct_index":0,"explanation":"Umahluko phakathi kwesicwangciso nesenzo unokutyhila ukungaqiniseki okanye umnqweno wokuba kuze umntu.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki."},{"question":"Leliphi ilungelo lokutolika elixhaswayo?","options":["Umbalisi akaze alinde nabani na.","Ukulinda kunokubonisa ukuba ukuhamba kunzima kuye.","Isitshixo singqina ukuba indlu iyatsha.","Umntu olindelweyo ngokuqinisekileyo ngumntakwabo."],"correct_index":1,"explanation":"Ukutolika okuhle kusondela kwiinkcukacha zesicatshulwa kwaye kuvume ukuba ulwazi oluthile alunikiwanga.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki."},{"question":"Ingaba siyamazi umntu olindelweyo?","options":["Ewe; ngutitshala ogama linguLizo.","Ewe; ngowona mfundi upase kakhulu.","Hayi; isicatshulwa asimchazi.","Ewe; ligosa lethala."],"correct_index":2,"explanation":"Akukho gama okanye budlelwane bunikiweyo. Ukwazi umda wolwazi yinxalenye yokufunda ngokunzulu.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ilizwi lombalisi nentsingiselo efihlakeleyo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","xhhl"],"metadata":{"term":4,"focus":"Ilizwi lombalisi nentsingiselo efihlakeleyo","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=hEkvWcfU0LI%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"6059a735-8c23-5a53-b4cc-23147e5be600","title":"isiZulu HL · Grade 11 · Term 2: Ukufingqa nengxoxo esekelwe embhalweni","subject":"isiZulu HL","grade":"Grade 11","questions":[{"question":"Yisiphi isifingqo esinembile?","options":["Bonke abafundi bayawuphikisa umbono.","Amatekisi azoba khona ubusuku bonke.","Indawo yokufunda iyasekelwa, kodwa ezokuthutha zisadinga isixazululo.","Ikomiti selakhe isakhiwo esisha."],"correct_index":2,"explanation":"Isifingqo sigcina umqondo obalulekile kanye nesithiyo sokufinyelela, singangezi isinqumo esingakathathwa.","stimulus":"Ikomiti lesikole liphakamisa indawo yokufunda ntambama. Abafundi abaningi bayawusekela umbono, kodwa abanye bathi itekisi lokugcina lihamba kusenesikhathi. Ikomiti lizobuza nangezokuthutha."},{"question":"Liyini iqhaza legama kodwa?","options":["Lisho ukuthi wonke umuntu uyavuma.","Libala abafundi.","Lethula igama lomuntu.","Lethula ukuphikisana noma umkhawulo embonweni odlule."],"correct_index":3,"explanation":"Kodwa lixhumanisa ukusekela umbono nenkinga yokuthutha. Lenza umfundi abone izinhlangothi zombili.","stimulus":"Ikomiti lesikole liphakamisa indawo yokufunda ntambama. Abafundi abaningi bayawusekela umbono, kodwa abanye bathi itekisi lokugcina lihamba kusenesikhathi. Ikomiti lizobuza nangezokuthutha."},{"question":"Yiluphi uphenyo olungasiza isinqumo?","options":["Buza abafundi ngezikhathi zokuthutha nokutholakala kwabo.","Buza ngemibala abayithandayo kuphela.","Ungababuzi abasebenzisa amatekisi.","Bala amawindi kuphela."],"correct_index":0,"explanation":"Ulwazi lokuthutha luhlobene ngqo nenkinga. Ukushiya iqembu elithintekayo kungachema imiphumela.","stimulus":"Ikomiti lesikole liphakamisa indawo yokufunda ntambama. Abafundi abaningi bayawusekela umbono, kodwa abanye bathi itekisi lokugcina lihamba kusenesikhathi. Ikomiti lizobuza nangezokuthutha."},{"question":"Yiliphi igama okufanele lingaguqulwa libe bonke?","options":["Bonke","Abaningi","Ngamunye","Nakanjani bonke"],"correct_index":1,"explanation":"Abaningi akusho bonke. Ukushintsha leli gama kungakhulisa isimangalo kunobufakazi obukhona.","stimulus":"Ikomiti lesikole liphakamisa indawo yokufunda ntambama. Abafundi abaningi bayawusekela umbono, kodwa abanye bathi itekisi lokugcina lihamba kusenesikhathi. Ikomiti lizobuza nangezokuthutha."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukufingqa nengxoxo esekelwe embhalweni. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","zuhl"],"metadata":{"term":2,"focus":"Ukufingqa nengxoxo esekelwe embhalweni","language":"zu","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Fm1a-qg8adg%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"f6cf5b33-bf36-5100-98d3-4dfc0dd0fb3d","title":"isiZulu HL · Grade 11 · Term 3: Ukufunda ngokucophelela nokuhlola isimangalo","subject":"isiZulu HL","grade":"Grade 11","questions":[{"question":"Iyiphi inkinga enkulu ebufakazini?","options":["Akekho umuntu ongafunda kulolu hlelo.","Amamaki awakwazi ukukalwa.","Zonke izikhangiso zingamanga.","Umfundi oyedwa akanele ukufakazela umphumela kubo bonke."],"correct_index":3,"explanation":"Isampula incane futhi akukho kuqhathanisa okunikeziwe. Lokhu akufakazeli ukuthi uhlelo alukwazi ukusiza muntu.","stimulus":"Inhlangano ithi uhlelo lwayo lukhuphula amamaki. Esikhangisweni kusebenziswa amazwi omfundi oyedwa. Awanikezwa amamaki angaphambi kohlelo noma iqembu lokuqhathanisa."},{"question":"Yisiphi isimangalo esilinganiselayo?","options":["Omunye umfundi ubika inzuzo; kudingeka ucwaningo olubanzi.","Uhlelo luqinisekisa impumelelo kubo bonke.","Akekho umfundi ongazuza.","Isikhangiso sesifakazele imbangela."],"correct_index":0,"explanation":"Impendulo igcina ulwazi olukhona icacise nomkhawulo walo, ingathembisi umphumela ongakalinganiswa.","stimulus":"Inhlangano ithi uhlelo lwayo lukhuphula amamaki. Esikhangisweni kusebenziswa amazwi omfundi oyedwa. Awanikezwa amamaki angaphambi kohlelo noma iqembu lokuqhathanisa."},{"question":"Yiluphi ulwazi olungaqinisa ukuhlola?","options":["Inani lemibala kuphela.","Amamaki angaphambi nangemva kanye neqembu eliqhathanisekayo.","Igama lomshicileli kuphela.","Ubukhulu belogo kuphela."],"correct_index":1,"explanation":"Ukuqhathanisa okuhle kungasiza ukuhlola ushintsho kanye nezinye izizathu ezingaluchaza.","stimulus":"Inhlangano ithi uhlelo lwayo lukhuphula amamaki. Esikhangisweni kusebenziswa amazwi omfundi oyedwa. Awanikezwa amamaki angaphambi kohlelo noma iqembu lokuqhathanisa."},{"question":"Kungani kubalulekile ukucabanga ngenhloso yombhali?","options":["Inhloso iqinisekisa ukuthi zonke izimangalo ziyiqiniso.","Inhloso isusa isidingo sobufakazi.","Angase afune ukuthengisa uhlelo agcizelele izinzuzo.","Umbhali akakwazi ukukhetha ulwazi."],"correct_index":2,"explanation":"Ukuqonda inhloso yokuthengisa kusiza ukubuza ukuthi yikuphi okugcizelelwe nokushiywe ngaphandle.","stimulus":"Inhlangano ithi uhlelo lwayo lukhuphula amamaki. Esikhangisweni kusebenziswa amazwi omfundi oyedwa. Awanikezwa amamaki angaphambi kohlelo noma iqembu lokuqhathanisa."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukufunda ngokucophelela nokuhlola isimangalo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","zuhl"],"metadata":{"term":3,"focus":"Ukufunda ngokucophelela nokuhlola isimangalo","language":"zu","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Fm1a-qg8adg%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"083fc9de-0129-5be6-94e0-5f2196569388","title":"isiZulu HL · Grade 11 · Term 4: Umbalisi nencazelo engashiwo ngqo","subject":"isiZulu HL","grade":"Grade 11","questions":[{"question":"Ngubani obalisa le ndaba?","options":["Umlingiswa obalisa okwenzeke kuye.","Umbalisi ongakaze abe yingxenye yesigameko.","Abantu abaningi abakhuluma kanye.","Isikhangiso sesitolo."],"correct_index":0,"explanation":"Izenzo ezithi Ngabeka, ngizohamba, ngalinda zibonisa umuntu wokuqala. Sithola umbono wakhe ngezigameko.","stimulus":"Ngabeka ukhiye etafuleni. Ngangithe ngizohamba ngingabheki emuva. Kodwa ngama emnyango ngalinda, ngilalele izinyathelo ezazingafiki."},{"question":"Yikuphi ukuphikisana okubalulekile?","options":["Ukhiye uphenduka incwadi.","Umbalisi uthi uzohamba kodwa uyama alinde.","Izinyathelo zifika ngokushesha.","Umnyango uyakhuluma."],"correct_index":1,"explanation":"Umehluko phakathi kwesinqumo nesenzo ungaveza ukungaqiniseki noma ukulangazelela ukufika kothile.","stimulus":"Ngabeka ukhiye etafuleni. Ngangithe ngizohamba ngingabheki emuva. Kodwa ngama emnyango ngalinda, ngilalele izinyathelo ezazingafiki."},{"question":"Yikuphi ukuhumusha okusekelwa umbhalo?","options":["Umbalisi akalindi muntu nhlobo.","Ukhiye ufakazela ukuthi indlu iyasha.","Ukulinda kungasikisela ukuthi ukuhamba kunzima kuye.","Olindelwe ngumfowabo ngokuqinisekile."],"correct_index":2,"explanation":"Ukuhumusha okuhle kusebenzisa imininingwane ethile kuvume nokuthi okunye akushiwo.","stimulus":"Ngabeka ukhiye etafuleni. Ngangithe ngizohamba ngingabheki emuva. Kodwa ngama emnyango ngalinda, ngilalele izinyathelo ezazingafiki."},{"question":"Siyamazi yini umuntu olindelwe?","options":["Yebo; nguthisha ogama lakhe uLizo.","Yebo; ngumfundi ohamba phambili.","Yebo; ngumsebenzi womtapo wezincwadi.","Cha; umbhalo awumchazi."],"correct_index":3,"explanation":"Alikho igama noma ubudlelwano obunikeziwe. Ukuqaphela imikhawulo yolwazi kuyingxenye yokufunda okujulile.","stimulus":"Ngabeka ukhiye etafuleni. Ngangithe ngizohamba ngingabheki emuva. Kodwa ngama emnyango ngalinda, ngilalele izinyathelo ezazingafiki."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Umbalisi nencazelo engashiwo ngqo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","zuhl"],"metadata":{"ter